export const getGetAgentMessagesUrl = (sessionId: string,
    params?: GetAgentMessagesParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/chat/${sessionId}/agent-messages?${stringifiedParams}` : `/api/chat/${sessionId}/agent-messages`
}

